import ast,json,pathlib,subprocess,sys
p=pathlib.Path(json.loads(pathlib.Path('/private/tmp/oe-historical-refusal-pointer.json').read_text())['local']);sys.path.insert(0,str(p));from transport import remote,sha
state=json.loads((p/'state.json').read_text());dest=state['root'].replace('\\','/')
tree=ast.parse((p/'transport.py').read_text());alias=next(n.value.elts[5].value for n in ast.walk(tree) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='argv' for t in n.targets))
inputs=['source.tar','source-manifest.json','historical-git-manifest.json','public-api-review.json','common.ps1','audit.ps1','build.ps1','runtime-common.ps1','run.ps1','postflight.ps1','state-input.json','native-tool-reference.json']
(p/'final-input-hashes.json').write_text(json.dumps([{'path':f,'sha256':sha(p/f)} for f in inputs],indent=2)+'\n')
files=inputs+['final-input-hashes.json'];c=subprocess.run(['scp','-O','-q','-o','BatchMode=yes','-o','ConnectTimeout=8']+[str(p/f) for f in files]+[alias+':'+dest+'/'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=55)
(p/'transfer-build.stdout').write_bytes(c.stdout);(p/'transfer-build.stderr').write_bytes(c.stderr);(p/'transfer-build.json').write_text(json.dumps({'exit':c.returncode,'files':len(files),'stdout_sha256':sha(p/'transfer-build.stdout'),'stderr_sha256':sha(p/'transfer-build.stderr')},indent=2)+'\n');assert c.returncode==0
script="$root='"+state['root']+r"';$ErrorActionPreference='Stop';foreach($e in @(Get-Content -Raw (Join-Path $root 'final-input-hashes.json')|ConvertFrom-Json)){if((Get-FileHash (Join-Path $root $e.path) -Algorithm SHA256).Hash -ne $e.sha256){throw 'input transfer hash mismatch'};(Get-Item (Join-Path $root $e.path)).IsReadOnly=$true};(Get-Item (Join-Path $root 'final-input-hashes.json')).IsReadOnly=$true;foreach($name in @('common.ps1','audit.ps1','build.ps1','runtime-common.ps1','run.ps1','postflight.ps1')){$tokens=$null;$errors=$null;$null=[System.Management.Automation.Language.Parser]::ParseFile((Join-Path $root $name),[ref]$tokens,[ref]$errors);if($errors.Count -gt 0){throw ($errors|Out-String)}};& (Join-Path $root 'build.ps1')"
r,out=remote('build-attached',script,timeout=1400,exe='pwsh.exe');print(json.dumps(r),flush=True);print(out.replace(state['root'],'<HISTORICAL_FIXTURE>')[:1800],flush=True)
